\caption{Explore-then-commit empirical-success policy~$\tilde{\pi}$ \label{alg}}\label{poly:ES}
\For{$t = 1, \hdots, n_1(n) :=  \min(K \lceil n^{2/3} \rceil, n)$}{assign~$\tilde{\pi}_{n,t}(Z_{t-1}, G_t) = G_t$, with~$G_t$ uniformly distributed on~$\mathcal{I}$} 
\For{$t = n_1(n)+1, \hdots, n$}{assign~$\tilde{\pi}_{n,t}(Z_{t-1}, G_t) = \min \argmax\limits_{i: S_{i, n}(n_1(n)) > 0} \mathsf{T}(\hat{F}_{i,n_1(n), n})$}

source.quote:
Under Assumptions \ref{as:MAIN} and \ref{as:MB}, the F-UCB policy~$\hat{\pi}$ satisfies
\begin{align}\label{eq:probres}
\P\del[3]{R_n(\hat{\pi})> \sum_{i:\Delta_i>0}\del[2]{\frac{2C^2\beta\log(n)}{\Delta_i}+\Delta_i}x}
\leq
\frac{2K}{n^{\beta x-1}}+2\sum_{i:\Delta_i>0}\frac{\del[1]{\frac{2C^2\beta\log(n)}{\Delta_i^2}x}^{1-\beta}}{\beta-1}
\end{align}	
for every~$n\in\N$ and~$x\geq 1$.
